example.code:
// Basic usage: measure the execution time of an operation.
var sw = ValueStopwatch.StartNew();
Thread.Sleep(100);
var elapsed = sw.Elapsed;
Console.WriteLine($"Elapsed: {elapsed.TotalMilliseconds} ms");

// Use on performance-critical paths.
var stopwatch = ValueStopwatch.StartNew();
PerformanceTestOperation();
if (stopwatch.Elapsed.TotalMilliseconds > 1000)
{
    Console.WriteLine("Operation timed out");
}

var options = new HayatePoolOptions
{
    EnableCircuitBreaker = true,
    CircuitBreaker = new HayateCircuitBreakerOptions
    {
        FailureThreshold = 3,
        ResetTimeout = TimeSpan.FromSeconds(30),
        ProbeInterval = TimeSpan.FromSeconds(5),
        Probe = () => database.Ping()
    }
};

