 lease.Value.DoWork();

 var asyncLease = await pool.AcquireScopeAsync(ct);
 using (asyncLease) { asyncLease.Value.DoWork(); }

var obj = await pool.AcquireAsync(TimeSpan.FromSeconds(3), cancellationToken);
try { /* use obj */ }
finally { pool.Release(obj); }

 var pools = new ParameterizedHayatePool<string, Connection>(
     connectionString => new Connection(connectionString),
     maxSizePerKey: 8);

 var connection = pools.GetObject("tenant-a");
 try { connection.Query("..."); }
 finally { pools.ReturnObject("tenant-a", connection); }

member.param:
An optional callback that adjusts the options of the sub-pool being created
            for a key — an eviction interval, a breaker, a scaling strategy. Applied to a copy of the defaults,
            so it cannot affect other keys.

example.code:
var pools = new ParameterizedHayatePool<string, Connection>(
    cs => new Connection(cs),
    maxSizePerKey: 8,
    onGet: (cs, connection) => connection.Open(cs));

var connection = pools.GetObject("tenant-a");
try { connection.Query("..."); }
finally { pools.ReturnObject("tenant-a", connection); }

var connection = await pools.GetObjectAsync("tenant-a", cancellationToken);
try { await connection.QueryAsync("..."); }
finally { pools.ReturnObject("tenant-a", connection); }
